/**
 * TelemetryPanel: Simulated CAN / FDCAN Message Monitor
 *
 * Terminal / diagnostic table displaying real-time frames generated by the STM32H7:
 * - Timestamps (s), 11-bit CAN IDs, Message Names, DLC, Raw Hex, Decoded Engineering Values
 * - Bus status pill (OPERATIONAL vs BUS-OFF)
 * - Auto-scroll toggle and ID filter
 */

import React, { useState } from 'react';
import { RadioTower, Pause, Play, Trash2, Filter } from 'lucide-react';
import { formatHex, formatHexBytes, formatTimestamp } from '../utils/formatters.js';

export function TelemetryPanel({ telemetry, isHealthy = true }) {
  const [isPaused, setIsPaused] = useState(false);
  const [filterId, setFilterId] = useState('ALL');

  const messages = telemetry.messages || [];

  const filteredMessages = messages.filter((m) => {
    if (filterId === 'ALL') return true;
    return formatHex(m.canId) === filterId;
  });

  return (
    <div className="telemetry-container">
      {/* Telemetry Header */}
      <div className="telemetry-header">
        <div className="telemetry-title-group">
          <RadioTower size={15} className={isHealthy ? 'text-purple-400' : 'text-red-400'} />
          <span className="font-semibold text-slate-200 text-sm">
            STM32H7 FDCAN1 Telemetry Bus Monitor &bull; <span>Simulated CAN-FD Protocol</span>
          </span>
          <span className={`bus-badge ${isHealthy ? 'bus-ok' : 'bus-fail'}`}>
            {telemetry.busStatus}
          </span>
        </div>

        <div className="telemetry-controls">
          {/* Filter Dropdown */}
          <div className="flex items-center gap-1.5 text-xs text-slate-400">
            <Filter size={12} />
            <select
              value={filterId}
              onChange={(e) => setFilterId(e.target.value)}
              className="can-filter-select"
            >
              <option value="ALL">All Frames</option>
              <option value="0x180">0x180 (Speed/PWM)</option>
              <option value="0x181">0x181 (Electrical)</option>
              <option value="0x182">0x182 (Thermal)</option>
              <option value="0x183">0x183 (Encoder)</option>
              <option value="0x070">0x070 (Emergency)</option>
            </select>
          </div>

          <button
            className={`can-btn ${isPaused ? 'active' : ''}`}
            onClick={() => setIsPaused(!isPaused)}
            title={isPaused ? 'Resume live stream' : 'Pause scrolling'}
          >
            {isPaused ? <Play size={12} /> : <Pause size={12} />}
            <span>{isPaused ? 'Resume' : 'Pause'}</span>
          </button>
        </div>
      </div>

      {/* Message Table */}
      <div className="telemetry-table-wrapper">
        <table className="telemetry-table">
          <thead>
            <tr>
              <th>Time</th>
              <th>CAN ID</th>
              <th>Frame Name</th>
              <th>DLC</th>
              <th>Payload (Hex)</th>
              <th>Decoded Physical Values</th>
              <th>Status</th>
            </tr>
          </thead>
          <tbody>
            {!isHealthy ? (
              <tr>
                <td colSpan={7} className="text-center py-6 text-red-400 font-mono text-xs">
                  [CAN BUS PASSIVE / ERROR BUS-OFF]: Transceiver communication failed or cable disconnected. No telemetry frames transmitted.
                </td>
              </tr>
            ) : filteredMessages.length === 0 ? (
              <tr>
                <td colSpan={7} className="text-center py-6 text-slate-500 font-mono text-xs">
                  No CAN messages recorded yet. Start simulation to transmit telemetry.
                </td>
              </tr>
            ) : (
              filteredMessages.slice(0, 30).map((msg) => (
                <tr
                  key={msg.id}
                  className={`can-row ${msg.canId === 0x070 ? 'row-alert' : ''}`}
                >
                  <td className="font-mono text-slate-400">
                    {formatTimestamp(msg.timestamp)}
                  </td>
                  <td className="font-mono text-cyan-300 font-semibold">
                    {formatHex(msg.canId)}
                  </td>
                  <td className="font-mono text-slate-200">
                    {msg.name}
                  </td>
                  <td className="font-mono text-slate-400">
                    {msg.dlc}
                  </td>
                  <td className="font-mono text-amber-300/90 text-xs tracking-wider">
                    {formatHexBytes(msg.data)}
                  </td>
                  <td className="font-mono text-slate-300 text-xs">
                    {msg.decoded}
                  </td>
                  <td>
                    <span
                      className={`status-pill-small ${
                        msg.status === 'ALERT'
                          ? 'pill-small-alert'
                          : msg.status === 'WARN'
                          ? 'pill-small-warn'
                          : 'pill-small-ok'
                      }`}
                    >
                      {msg.status}
                    </span>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}
